  if (str.length === 1) return true;
  let l = 0;
  let r = str.length - 1;
  const isDigit = (char) => {
    if (!char || typeof char !== 'string') return false;
    const baseCode = "0".codePointAt();
    const digit = char.codePointAt() - baseCode;
    return digit >= 0 && digit <= 9;
  }
  const isLetter = (char) => {
    if (!char) return false;
    return char.toLowerCase() !== char.toUpperCase();
  }
  while (l < r) {
    const lchar = str[l];
    const rchar = str[r];
    if (!isLetter(lchar) && !isDigit(lchar)) {
      l++;
      continue;
    }
    if (!isLetter(rchar) && !isDigit(rchar)) {
      r--;
      continue;
    }
    if (lchar.toLowerCase() !== rchar.toLowerCase()) return false;
    l++;
    r--;
  }
  return true;
}

